backgroundColor:
{{
  (() => {
    const currentTab = appsmith.store.tab_achats || 'A_COMMANDER';
    const total = Number(currentItem.Total_HT || 0);
    const franco = Number(currentItem.Franco_De_Port || 0);

    // 1. Onglet À COMMANDER : Gestion du Franco
    if (currentTab === 'A_COMMANDER') {
      if (franco > 0 && total >= franco) {
        return "#dcfce7"; // Vert clair
      }
      return "#ffffff";
    }

    // 2. Onglet EN COMMANDE : Gestion des retards dynamiques
    if (currentTab === 'EN_COMMANDE') {
      const poolData = Array.isArray(Get_Achats_Pool.data) ? Get_Achats_Pool.data : [];

      const articlesEnCommande = poolData.filter(r => 
        (currentItem.ID_Fournisseur === 'TOUS' || (r.ID_Fournisseur || 'NON_ASSIGNE') === currentItem.ID_Fournisseur) &&
        ['COMMANDÉ', 'COMMANDE', 'REÇU PARTIEL', 'RECU PARTIEL'].includes((r.Statut_Achat || '').toUpperCase()) &&
        (r.Date_Livraison_Prevue || r.Date_Commande) // 👈 Sécurité sur l'une ou l'autre date
      );

      let maxJoursAttente = 0;

      // 👈 CORRECTION : moment() est dynamique, il prendra toujours la vraie date du jour
      const aujourdhui = moment().startOf('day');

      articlesEnCommande.forEach(article => {

        // 👈 NOUVEAUTÉ : S'il y a une date de livraison prévue, on calcule le délai à partir d'elle.
        // Sinon, on calcule depuis la date de création de la commande.
        const dateReference = article.Date_Livraison_Prevue 
          ? moment(article.Date_Livraison_Prevue).startOf('day') 
          : moment(article.Date_Commande).startOf('day');

        const diffJours = aujourdhui.diff(dateReference, 'days');

        if (diffJours > maxJoursAttente) {
          maxJoursAttente = diffJours;
        }
      });

      if (maxJoursAttente > 10) return "#fee2e2"; // Rouge clair (> 10 jours de retard)
      if (maxJoursAttente > 4) return "#ffedd5";  // Orange clair (> 4 jours de retard)

      return "#ffffff"; // Blanc si dans les temps (ou présaison future)
    }

    return "#ffffff";
  })()
}}
